ee:variables.ee:set-variable:
%dw 2.0
output application/json
var stockMap = vars.availableQuantity groupBy ($.sku)

var checkedItems = vars.requestedQuantity map (req) -> {
    sku: req.sku,
    requested_qty: req.quantity,
    exists: stockMap[req.sku]?,
    sufficient: (stockMap[req.sku][0].quantity_available default 0) >= req.quantity,
    available_qty: stockMap[req.sku][0].quantity_available default 0
}
---

{
    eligibleItems: checkedItems filter (i) -> i.exists and i.sufficient,
    ineligibleItems: checkedItems filter (i) -> (not i.exists) or (not i.sufficient),
    hasEligible: isEmpty(checkedItems filter (i) -> i.exists and i.sufficient) == false
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
var totalOrders = sizeOf(payload)
var totalOrdersPlaced = sizeOf(payload filter (item) -> item.orderId != null)
---

{
    phoneNumber: payload.phoneNumber[0],
    requestStatus: if(totalOrdersPlaced == totalOrders) "ALL_SUCCESS" else if(totalOrdersPlaced == 0) "ALL_FAILURE" else "PARTIAL_SUCCESS",
    itemsResult: payload map (item) -> {
        sku: item.sku,
        quantity: item.quantity,
        status: if(item.isEligible) "Order Placed" else "Sorry, not placed"
    } ++  if(item.isEligible) {
        orderId: item.orderId
    } else {}
}

%dw 2.0
output application/json
---
{
    phoneNumber: vars.orderObject.customer.phoneNumber,
    requestStatus: "ALL_FAILURE",
    itemsResult: vars.orderObject.items map (item) -> item ++ {
        failureReason: "SKU does not exists."
	}
}

%dw 2.0
output application/json
---
{
    "stock": payload map ((item) -> item ++  {
        "isAvailable": item.quantity_available > 0
    })
}
